Dataspatium.assets.register("presets/api/sundsvall-riges.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"sundsvall-riges\",\n  \"name\": \"Sundsvall med grannkommuner: detaljplaner i NGP-form (WFS)\",\n  \"publisher\": \"Sundsvalls kommun\",\n  \"description\": \"Detaljplaner i Lantmäteriets NGP-form för Sundsvall, Örnsköldsvik, Härnösand, Timrå, Ånge, Kramfors och Sollefteå (arbetsytan RIGES i Sundsvalls GeoServer): planernas ytor, användnings-, egenskaps- och administrativa bestämmelser med Boverkets katalogreferens. Sök en plan på namn eller beteckning och hämta den hel som detaljplan, eller hämta ett lager som karta. Ingen nyckel.\",\n  \"docs\": \"https://karta.sundsvall.se/\",\n  \"license\": {\n    \"name\": \"Villkor anges inte av tjänsten\",\n    \"url\": \"https://karta.sundsvall.se/\"\n  },\n  \"level\": 1,\n  \"country\": \"SE\",\n  \"baseUrl\": \"https://karta.sundsvall.se/geoserver/RIGES/wfs\",\n  \"auth\": {\n    \"type\": \"none\"\n  },\n  \"cors\": {\n    \"file\": true,\n    \"web\": true\n  },\n  \"family\": {\n    \"type\": \"geodata\",\n    \"kind\": \"wfs\"\n  },\n  \"endpoints\": [],\n  \"notes\": \"Lagren läses från tjänsten när källan öppnas (GetCapabilities, cirka 36 lager). Överst i listan söker Detaljplaner (hela planer) bland cirka 2 100 planer och hämtar en plan ur alla NGP-lagren. CORS från file:// och webben verifierat 2026-11-28.\",\n  \"i18n\": {\n    \"en\": {\n      \"name\": \"Sundsvall and neighbouring municipalities: detailed plans in NGP form (WFS)\",\n      \"publisher\": \"Sundsvall municipality\",\n      \"description\": \"Detailed development plans in Lantmäteriet's NGP form for Sundsvall, Örnsköldsvik, Härnösand, Timrå, Ånge, Kramfors and Sollefteå (the workspace RIGES of Sundsvall's GeoServer): the plans' areas and their use, property and administrative provisions with Boverket's catalogue reference. Find a plan by name or designation and fetch it whole as a detailed plan, or fetch a layer as a map. No key.\",\n      \"notes\": \"The layers are read from the service when the source is opened (GetCapabilities, about 36 layers). At the top of the list, Detailed plans (whole plans) searches about 2,100 plans and fetches a plan from all the NGP layers. CORS from file:// and the web verified on 2026-11-28.\"\n    },\n    \"da\": {\n      \"name\": \"Sundsvall and neighbouring municipalities: detailed plans in NGP form (WFS)\"\n    },\n    \"nb\": {\n      \"name\": \"Sundsvall and neighbouring municipalities: detailed plans in NGP form (WFS)\"\n    },\n    \"fi\": {\n      \"name\": \"Sundsvall and neighbouring municipalities: detailed plans in NGP form (WFS)\"\n    },\n    \"is\": {\n      \"name\": \"Sundsvall and neighbouring municipalities: detailed plans in NGP form (WFS)\"\n    }\n  }\n}\n");
